package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	// Helper to read next int
	readInt := func() int {
		scanner.Scan()
		val, _ := strconv.Atoi(scanner.Text())
		return val
	}

	n := readInt()
	m := readInt()
	c0 := readInt()
	d0 := readInt()

	// Initialize DP array
	// dp[j] = max money using j grams of dough
	dp := make([]int, n+1)

	// Process each stuffing type
	for i := 0; i < m; i++ {
		a := readInt()
		b := readInt()
		c := readInt()
		d := readInt()

		// Max buns possible with this stuffing
		maxBuns := a / b

		// Multiple knapsack: process backwards to avoid reuse in same iteration
		// But since we have a limit on number of items (maxBuns), we can use binary optimization or simple loop
		// Given constraints (n=1000, m=10, maxBuns <= 100), simple O(n * maxBuns) is fine.
		// We iterate dough capacity backwards for 0/1 knapsack style per bun,
		// but since we can make multiple buns of same type, we need bounded knapsack.
		// Easiest: create a new dp array for each stuffing type, or iterate backwards and inner loop over count.
		// Standard bounded knapsack: for cap from n down to 0, for k=1 to maxBuns if k*c <= cap.
		// Or optimize by treating as multiple 0/1 items (binary splitting), but not needed for n=1000.

		// We'll use a temporary array or update backwards carefully.
		// Since we can make 0 to maxBuns buns of this type, it's a group knapsack for this type.
		// new_dp[cap] = max over k (dp[cap - k*c] + k*d)
		// We can compute this by iterating cap from 0 to n and k, but need previous state.
		// Better: iterate cap from n down to 0, and for each cap try k=1..maxBuns.
		// Wait, if we iterate cap downwards, and use dp[cap - k*c], that state hasn't been updated for this stuffing type yet (since cap - k*c < cap). So it's correct.

		for cap := n; cap >= 0; cap-- {
			for k := 1; k <= maxBuns; k++ {
				doughNeeded := k * c
				if doughNeeded > cap {
					break
				}
				val := dp[cap-doughNeeded] + k*d
				if val > dp[cap] {
					dp[cap] = val
				}
			}
		}
	}

	// Now process buns without stuffing (unbounded knapsack, or just fill remaining dough)
	// Since c0, d0 are constant, we can just compute for each capacity the max by adding plain buns.
	// Actually, plain buns can be made at any time. It's equivalent to: for each capacity, we can add plain buns.
	// We can do a final pass: for cap from 0 to n, dp[cap] = max(dp[cap], dp[cap - c0] + d0) iteratively? 
	// Or simpler: since plain buns are unbounded, we can treat it as complete knapsack at the end.
	for cap := c0; cap <= n; cap++ {
		val := dp[cap-c0] + d0
		if val > dp[cap] {
			dp[cap] = val
		}
	}

	// The answer is max over all capacities up to n? 
	// "Lavrenty throws away all excess material left after baking." So we don't have to use all dough.
	// We want max money for any dough usage <= n.
	ans := 0
	for i := 0; i <= n; i++ {
		if dp[i] > ans {
			ans = dp[i]
		}
	}

	fmt.Println(ans)
}
